\begin{defn}
If $A$ is a set of sets, then $\bigcap A$ is the set of objects which
all elements of~$A$ have in common:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{ belongs to every !!{element} of } A},
\text{ i.e.,}\\
 & = \Setabs{x}{\text{for all } B \in A, x \in B}
\end{align*}
\end{defn}

target_before.text:
\begin{defn}
جے $A$ سیٹاں دا سیٹ اے، تاں $\bigcap A$ اوہناں شےواں دا سیٹ اے جو
$A$ دے سارے عنصراں وچ سانجھیاں نیں:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{، سیٹ } A\text{ دے ہر !!{element} وچ اے}},
\text{ یعنی،}\\
 & = \Setabs{x}{\text{ہر } B \in A, x \in B}
\end{align*}
\end{defn}

